const REVIEWED_COMMIT = "005202a18108c5b287fe98467f9dabfa93d17508";
const REVIEWED_AT = "2026-08-29";

const reviewedUrl = (path: string) =>
  `https://github.com/${REVIEWED_REPO}/blob/${REVIEWED_COMMIT}/${path}`;

const labels = {
  en: {
    actual: "Actual project block",
    source: "Reviewed source",
    what: "What happens",
    why: "Why this block exists",
    state: "State before → after",
    breakage: "What breaks if you remove or change it",
  },
  uk: {
    actual: "Реальний блок проєкту",
    source: "Перевірене джерело",
    what: "Що відбувається",
    why: "Навіщо цей блок існує",
    state: "Стан до → після",
    breakage: "Що зламається, якщо прибрати або змінити",
  },
} as const;

type WalkthroughSpec = {
  path: string;
  codeLanguage: string;
  code: string;
  what: string;
  whatUk: string;
  why: string;
  whyUk: string;
  state: string;
  stateUk: string;
  breakage: string;
  breakageUk: string;
};

function walkthroughConcept(language: "en" | "uk", spec: WalkthroughSpec) {
  const copy = labels[language];
  const localized = language === "uk";
  return [
    `### ${copy.actual}`,
    `[${copy.source}: \`${spec.path}\`](${reviewedUrl(spec.path)})`,
    `\`\`\`${spec.codeLanguage}`,
    spec.code,
    "```",
    `### ${copy.what}`,
    localized ? spec.whatUk : spec.what,
    `### ${copy.why}`,
    localized ? spec.whyUk : spec.why,
    `### ${copy.state}`,
    localized ? spec.stateUk : spec.state,
    `### ${copy.breakage}`,
    localized ? spec.breakageUk : spec.breakage,
  ].join("\n\n");
}

type LessonSpec = WalkthroughSpec & {
  id: string;
  order: number;
  title: string;
  titleUk: string;
  summary: string;
  summaryUk: string;
  keyPoints: string[];
  keyPointsUk: string[];
  pitfalls: string[];
  pitfallsUk: string[];
  exercise?: string;
  exerciseUk?: string;
  sourceIds: string[];
};

function lesson(spec: LessonSpec) {
  return {
    id: spec.id,
    moduleId: "desktop-automation-lab",
    level: "Advanced",
    order: spec.order,
    title: spec.title,
    titleUk: spec.titleUk,
    summary: spec.summary,
    summaryUk: spec.summaryUk,
    concept: walkthroughConcept("en", spec),
    conceptUk: walkthroughConcept("uk", spec),
    keyPoints: spec.keyPoints,
    keyPointsUk: spec.keyPointsUk,
    pitfalls: spec.pitfalls,
    pitfallsUk: spec.pitfallsUk,
    exercise: spec.exercise,
    exerciseUk: spec.exerciseUk,
    sourceIds: ["desktop-automation-lab-repo", ...spec.sourceIds],
  };
}

